const assert=require('node:assert/strict'),{Match,HEROES}=require('./hammer-core');let n=0;const test=(s,f)=>{f();n++;console.log('PASS '+s)},step=(m,t,inputs=[])=>{for(let i=0;i<t*60;i++)m.step(1/60,inputs)},at=(p,x,y)=>Object.assign(p,{cx:x,cy:y,x:x+.5,y:y+.5,target:null});function open(options={}){const m=new Match({mode:'duel',rivals:false,seed:3,...options});m.phase='playing';m.grid=m.grid.map((t,i)=>i%15===0||i%15===14||i<15||i>=180?'S':'.');for(const p of m.actors){p.inv=0;p.hp=3;p.maxHp=3};return m}
test('three formats and independent state',()=>{assert.equal(new Match().actors.length,4);assert.deepEqual(new Match({mode:'coop'}).actors.map(p=>p.team),[0,0,1,1]);assert.equal(new Match({mode:'duel',rivals:false}).actors.length,2);assert.equal(new Match().bombs,undefined)});
test('six original characters on both human slots',()=>{for(const id of Object.keys(HEROES)){const m=new Match({mode:'coop',p1:id,p2:id});assert.equal(m.actors[0].id,id);assert.equal(m.actors[1].id,id)}});
test('grid movement and steel/crate obstruction',()=>{const m=open(),p=m.actors[0];at(p,3,3);m.step(1/60,[{dir:1}]);assert(p.x>3.5&&p.x<4.5);step(m,.3);assert.equal(p.cx,4);m.grid[3*15+5]='S';step(m,.5,[{dir:1}]);assert.equal(p.cx,4)});
test('directional hammer hits once and cannot spam',()=>{const m=open(),p=m.actors[0],q=m.actors[1];at(p,3,3);at(q,4,3);p.dir=1;assert(m.attack(p));assert(!m.attack(p));step(m,.2);assert.equal(q.hp,2);step(m,.12);assert.equal(q.hp,2)});
test('walls stop attacks and wrong direction misses',()=>{const m=open(),p=m.actors[0],q=m.actors[1];at(p,3,3);at(q,4,3);p.dir=3;m.attack(p);step(m,.3);assert.equal(q.hp,3);p.cool=0;p.dir=1;m.grid[3*15+4]='S';m.attack(p);step(m,.3);assert.equal(q.hp,3)});
test('hammer destroys adjacent crates',()=>{const m=open(),p=m.actors[0];at(p,3,3);p.dir=1;m.grid[3*15+4]='B';m.attack(p);step(m,.2);assert.equal(m.grid[3*15+4],'.');assert.equal(m.scores[0],10)});
test('shield absorbs damage and expires',()=>{const m=open(),p=m.actors[0],q=m.actors[1];q.guard=2;q.guardTime=1;m.hit(p,q,2,0,0);assert.equal(q.hp,3);assert.equal(q.guard,1);step(m,1.1);assert.equal(q.guard,0)});
test('elimination awards KO, respawns with health and protection',()=>{const m=open(),p=m.actors[0],q=m.actors[1];m.hit(p,q,3,0,0);assert(q.alive);assert.equal(m.wins[0],1);assert.equal(p.kills,1);assert.deepEqual([q.cx,q.cy],q.spawn);assert.equal(q.hp,1);assert.equal(q.inv,1);assert(!m.hit(p,q,3,0,0));step(m,.9);assert(!m.hit(p,q,1,0,0));step(m,.15);assert(m.hit(p,q,1,0,0));assert.equal(q.hp,1);assert.equal(m.wins[0],2)});
test('cooperative allies never damage or score against each other',()=>{const m=open({mode:'coop'});assert(!m.hit(m.actors[0],m.actors[1],3,0,0));assert.equal(m.wins[0],0)});
test('exactly ten eliminations ends the game and freezes score',()=>{const m=open(),p=m.actors[0],q=m.actors[1];for(let i=0;i<10;i++){q.alive=true;q.hp=3;q.inv=0;m.hit(p,q,3,0,0)}assert.equal(m.phase,'finished');assert.equal(m.result.winner,0);assert.equal(m.wins[0],10);q.alive=true;q.inv=0;m.hit(p,q,3,0,0);assert.equal(m.wins[0],10)});
test('all six skills consume energy and have distinct effects',()=>{for(const id of Object.keys(HEROES)){const m=open({p1:id}),p=m.actors[0];assert(m.skill(p));assert.equal(p.energy,0);assert(!m.skill(p));if(id==='dora')assert.equal(p.guard,2);if(id==='nezha')assert.equal(p.haste,5);if(['soldier','mystic','goku'].includes(id))assert.equal(m.shots.length,1);if(id==='explorer')assert.equal(p.action.damage,2)}});
test('all weapons and recovery pickups work',()=>{const m=open(),p=m.actors[0];for(const type of ['heavy','thunder','boomerang','shield','heal','energy']){p.hp=1;p.energy=0;const it={i:0,type};m.items.push(it);m.pickup(p,it);if(['heavy','thunder','boomerang'].includes(type)){assert.equal(p.weapon,type);assert.equal(p.weaponTime,12)}if(type==='heal')assert.equal(p.hp,2);if(type==='energy')assert.equal(p.energy,40);if(type==='shield')assert.equal(p.hp,2)}});
test('returning weapon reverses and remembers hit targets',()=>{const m=open(),p=m.actors[0];at(p,6,6);p.dir=1;m.projectile(p,1,true);const s=m.shots[0];step(m,.5);assert(s.returned);assert(s.vx<0)});
test('pause freezes attacks, shield and respawn timing',()=>{const m=open();m.paused=true;const before=JSON.stringify(m.snapshot());step(m,2,[{attack:true,skill:true,dir:1}]);assert.equal(JSON.stringify(m.snapshot()),before)});
test('dense themed obstacles retain clear spawn routes',()=>{for(let map=0;map<3;map++)for(const mode of ['solo','coop','duel'])for(let seed=0;seed<10;seed++){const m=new Match({map,mode,seed});assert(m.grid.filter(t=>t==='B').length>=43);assert.deepEqual([...new Set(Object.values(m.obstacles).map(o=>o.variant))].sort(),[0,1,2]);for(const p of m.actors)for(let y=1;y<12;y++)for(let x=1;x<14;x++)if(Math.abs(x-p.spawn[0])+Math.abs(y-p.spawn[1])<=3)assert.notEqual(m.grid[y*15+x],'B');}});
test('reinforced wooden chests require two normal strikes',()=>{const m=open(),p=m.actors[0],i=49;at(p,3,3);p.dir=1;m.grid[i]='B';m.obstacles[i]={variant:2,hp:2};m.attack(p);step(m,.2);assert.equal(m.grid[i],'B');assert.equal(m.obstacles[i].hp,1);step(m,.4);m.attack(p);step(m,.2);assert.equal(m.grid[i],'.');assert.equal(m.scores[0],10);});
test('every actor respawns at original position even when occupied',()=>{const m=open({mode:'coop'});for(const p of m.actors){at(p,7,5);p.alive=false;p.target={x:8,y:5,progress:.2};p.action={};const q=m.actors.find(a=>a!==p);at(q,...p.spawn);m.respawn(p);assert.deepEqual([p.cx,p.cy],p.spawn);assert.deepEqual([p.x,p.y],[p.spawn[0]+.5,p.spawn[1]+.5]);assert.equal(p.target,null);assert.equal(p.action,null);assert.equal(p.hp,1);assert.equal(p.inv,1);}});
test('one HP start, shield two HP, mount three HP, death resets upgrades',()=>{for(const mode of ['solo','coop','duel']){const m=new Match({mode});m.phase='playing';for(const p of m.actors)assert.equal(p.hp,1);const p=m.actors[0],q=m.actors.find(a=>a.team!==p.team);const get=type=>{const it={type,i:0};m.items.push(it);m.pickup(p,it);};get('heal');assert.equal(p.hp,1);get('shield');assert.equal(p.hp,2);assert.equal(p.guard,0);get('mount');assert.equal(p.hp,3);assert(p.mounted);p.inv=0;m.hit(q,p,1,0,0);assert.equal(p.hp,2);assert(!p.mounted);p.inv=0;m.hit(q,p,2,0,0);assert.equal(p.hp,1);assert.equal(p.maxHp,1);assert(!p.mounted);assert.equal(p.inv,1);}});
test('slower movement and swing recovery apply to both humans',()=>{const m=open();for(const p of m.actors){assert.equal(p.speed,3.3);p.cool=0;assert(m.attack(p));assert.equal(p.cool,.56);p.cool=0;p.weapon='heavy';assert(m.attack(p));assert.equal(p.cool,.8);}const p=m.actors[0];p.weapon='normal';p.cool=0;m.attack(p);step(m,.5);assert(!m.attack(p));step(m,.08);assert(m.attack(p));});
let games=0;test('27 full AI matches across maps, difficulty and multiplayer formats reach ten KOs',()=>{for(let map=0;map<3;map++)for(const difficulty of ['easy','medium','hard'])for(const mode of ['solo','coop','duel']){const m=new Match({map,difficulty,mode,rivals:mode!=='duel',p1:Object.keys(HEROES)[games%6],p2:'goku',seed:20+games});for(const p of m.actors)p.human=false;for(let i=0;i<600*60&&m.phase!=='finished';i++){m.step(1/60);m.events.length=0;for(const p of m.actors){assert(Number.isFinite(p.x)&&Number.isFinite(p.y));assert(p.x>=1&&p.x<14&&p.y>=1&&p.y<12)}}assert.equal(m.phase,'finished',map+'/'+difficulty+'/'+mode);assert.equal(Math.max(...m.wins),10);games++;}});console.log(n+' Hammer checks passed; '+games+' full matches');
